# 28a  (A) benchmark with every equation refitted without the plot's installation fold; held-out mortality; (C) sensitivity of E6r and of projections to the death rule.
source("scripts/28_common.R"); RNGkind("L'Ecuyer-CMRG"); set.seed(20261113); NC <- as.integer(Sys.getenv("KOA_CORES", "5"))
b_in <- benchrun(function(x) list(sm = SMO[[x$p]], bg = bg, bm = bm)); benchsum(b_in, "(A0) benchmark of record: S1 out of fold, E4r and E6r fitted to all plots"); r0 <- sqrt(mean((b_in$o_ba - b_in$p_ba)^2)); stopifnot(nrow(b_in) == 182, abs(r0 - (if (RNGkind()[1] == "L'Ecuyer-CMRG") 6.76 else 6.74)) < 0.01)
FK <- parallel::mclapply(sort(unique(P$fold)), function(k) { bk <- s1fit(M[fold != k]); trn <- d[fold_s != k]; gk <- fitg(trn, bg, s1p(bk, trn$lbyi, trn$planted)); mt <- mfc[fold != k]; mk <- mlfitG(Xmat(mt, s1p(bk, mt$lbyi, mt$planted)), mt$died, log(mt$yip))
  te <- mfc[fold == k]; p <- 1 - exp(-exp(as.numeric(Xmat(te, s1p(bk, te$lbyi, te$planted)) %*% mk$b) + log(te$yip))); list(k = k, bs = bk, bg = gk$b, gconv = gk$conv, bm = mk$b, gmax = mk$gmax, ntrain_d = nrow(trn), ntrain_m = nrow(mt), pm = data.table(planted = te$planted, died = te$died, p = p, yip = te$yip)) }, mc.cores = NC)
names(FK) <- sapply(FK, `[[`, "k"); cat("\nfold refits: E4r optim codes", paste(sapply(FK, `[[`, "gconv"), collapse = " "), "; E6r largest gradients", paste(signif(sapply(FK, `[[`, "gmax"), 2), collapse = " "), "\n")
cat("range across folds: E4r ln(BYI)", paste(round(range(sapply(FK, function(x) x$bg[["lbyi"]])), 3), collapse = " to "), "; E4r planted", paste(round(range(sapply(FK, function(x) x$bg[["pl"]])), 3), collapse = " to "), "; E6r ln(RD)", paste(round(range(sapply(FK, function(x) x$bm[["lrd"]])), 3), collapse = " to "), "; E6r planted", paste(round(range(sapply(FK, function(x) x$bm[["planted"]])), 3), collapse = " to "), "\n")
fo <- setNames(P$fold, P$pid); b_ho <- benchrun(function(x) { q <- FK[[as.character(fo[[x$p]])]]; list(sm = s1p(q$bs, log(x$byi), x$pl), bg = q$bg, bm = q$bm) }); benchsum(b_ho, "(A1) benchmark with S1, E4r and E6r all refitted without the plot's installation fold")
fwrite(b_ho[, .(planted, h, o_surv, p_surv, o_qmd, p_qmd, o_ba, p_ba)], "out/check28_benchmark_heldout.csv")
pm <- rbindlist(lapply(FK, `[[`, "pm")); auc <- function(y, p) { r <- rank(p); n1 <- sum(y == 1); n0 <- sum(y == 0); (sum(r[y == 1]) - n1 * (n1 + 1) / 2) / (n1 * n0) }
cat("\n(A2) held-out mortality (tree-intervals in the held-out fold, interval probability)\n"); print(rbind(cbind(set = "all", pm[, .(n = .N, deaths = sum(died), expected = round(sum(p), 1), obs_over_exp = round(sum(died) / sum(p), 2), auc = round(auc(died, p), 3))]), cbind(set = "planted", pm[planted == 1, .(n = .N, deaths = sum(died), expected = round(sum(p), 1), obs_over_exp = round(sum(died) / sum(p), 2), auc = round(auc(died, p), 3))]), cbind(set = "natural", pm[planted == 0, .(n = .N, deaths = sum(died), expected = round(sum(p), 1), obs_over_exp = round(sum(died) / sum(p), 2), auc = round(auc(died, p), 3))])))
pin <- 1 - exp(-exp(as.numeric(Xmat(mfc) %*% bm) + log(mfc$yip))); cat("in sample for comparison: auc", round(auc(mfc$died, pin), 3), "; planted", round(auc(mfc$died[mfc$planted == 1], pin[mfc$planted == 1]), 3), "; natural", round(auc(mfc$died[mfc$planted == 0], pin[mfc$planted == 0]), 3), "\n")
pm[, dec := cut(p, quantile(p, 0:5 / 5), include.lowest = TRUE, labels = FALSE)]; cat("held-out calibration by fifth of predicted probability\n"); print(pm[, .(n = .N, deaths = sum(died), expected = round(sum(p), 1)), by = dec][order(dec)])
# ---- (C) death rules ----
cat("\n(C) death rules; S1 and E4r as adopted; E6r refitted under each rule; PSP removal intervals censored in all\n")
RULES <- list(adopted_confirmed = mfc, first_dead_record = prepmf(f$mf), confirmed_no_resurrected = mfc[!(resurrected_tree %in% TRUE)])
SCN <- rbind(data.table(planted = 1, byi = byiq[planted == 1, md]), data.table(planted = 0, byi = byiq[planted == 0, md]))
CR <- lapply(names(RULES), function(nm) { m <- RULES[[nm]]; ft <- mlfitG(Xmat(m), m$died, log(m$yip)); bb <- benchrun(function(x) list(sm = SMO[[x$p]], bg = bg, bm = ft$b))
  sc <- rbindlist(lapply(1:2, function(i) { L <- getL(SCN$planted[i]); z <- simx(L$DBH, L$HT, L$EXPF_c, SCN$byi[i], SCN$planted[i], 100, s1p(bs, log(SCN$byi[i]), SCN$planted[i]), bg, ft$b); data.table(rule = nm, origin = ifelse(SCN$planted[i] == 1, "planted", "natural"), year = c(20, 40, 100), BA = round(z[c(21, 41, 101), "BA"], 1), TPH = round(z[c(21, 41, 101), "TPH"]), RD = round(z[c(21, 41, 101), "RD"], 2)) }))
  list(coef = data.table(rule = nm, rows = nrow(m), deaths = sum(m$died), deaths_planted = sum(m$died[m$planted == 1]), gmax = signif(ft$gmax, 2), t(round(ft$b, 4)), hazard_planted = round(exp(ft$b[["planted"]]), 2)), bench = cbind(rule = nm, rbind(cbind(set = "all", sm1(bb)), cbind(set = "planted", sm1(bb[planted == 1])), cbind(set = "natural", sm1(bb[planted == 0])))), sc = sc) })
print(rbindlist(lapply(CR, `[[`, "coef"))); print(rbindlist(lapply(CR, `[[`, "bench"))); S <- rbindlist(lapply(CR, `[[`, "sc")); print(dcast(S, origin + year ~ rule, value.var = "BA")); print(dcast(S, origin + year ~ rule, value.var = "TPH"))
fwrite(S, "out/check28_deathrules_scenarios.csv"); saveRDS(list(FK = lapply(FK, function(x) x[c("k", "bs", "bg", "bm")]), CR = CR), "out/check28a.rds"); cat("28a done\n")
